<script lang="ts">
 import {onMount} from 'svelte';import {historicalParcelReference} from '../../lib/parcel-reference';import {DEFAULT_WEEKLY_BOOKING_HOURS, type WeeklyBookingHours} from '../../lib/booking';
 let {lang='en'}=$props<{lang?:'en'|'th'}>();const th=()=>lang==='th',T=(en:string,thai:string)=>th()?thai:en;
 let inventory=$state<any[]>([]),shipments=$state<any[]>([]),jobs=$state<any[]>([]),status=$state(''),busy=$state(false),counts=$state<Record<string,number>>({}),weights=$state<Record<string,number>>({}),prices=$state<Record<string,{usd:number;jpy:number;thb:number}>>({}),tracking=$state<Record<string,string>>({}),shippingServices=$state<Record<string,string>>({}),holdReasons=$state<Record<string,string>>({}),confirmed=$state<Record<string,boolean>>({}),settings=$state<any>({allowed_countries:[],shipping_rates:{},usd_thb:null,jpy_thb:null,pickup_enabled:true}),countryOptions=$state<{code:string;name:string}[]>([]),rateCountry=$state('TH'),rateService=$state('ems_local'),rateKg=$state(0.5),rateTHB=$state(0),bookingHours=$state<WeeklyBookingHours>(DEFAULT_WEEKLY_BOOKING_HOURS),bookingRanges=$state<Record<string,{start:string;end:string}>>({});
 const weekdays=[0,1,2,3,4,5,6],slotTimes=Array.from({length:24},(_,i)=>`${String(8+Math.floor(i/2)).padStart(2,'0')}:${i%2?'30':'00'}`),closeTimes=[...slotTimes,'20:00'];
 const weekdayName=(day:number)=>new Intl.DateTimeFormat(th()?'th':'en',{weekday:'long',timeZone:'Asia/Bangkok'}).format(new Date(Date.UTC(2024,0,7+day,12)));
 function rangeFrom(hours:Record<string,string>){const times=Object.keys(hours).sort();if(!times.length)return {start:'',end:''};const last=times.at(-1)!;const [h,m]=last.split(':').map(Number);const end=`${String(h+(m===30?1:0)).padStart(2,'0')}:${m===30?'00':'30'}`;return {start:times[0],end};}
 function validRange(day:number){const range=bookingRanges[String(day)];if(!range?.start&&!range?.end)return true;if(!range?.start||!range?.end)return false;const minutes=(value:string)=>Number(value.slice(0,2))*60+Number(value.slice(3));return minutes(range.end)-minutes(range.start)>=60;}
 function applyDayRange(day:number){const range=bookingRanges[String(day)];const next={...bookingHours};const row:Record<string,'available'|'contact_directly'>={};if(range?.start&&range?.end&&validRange(day)){for(const time of slotTimes){if(time>=range.start&&time<range.end)row[time]=bookingHours[String(day)]?.[time]==='contact_directly'?'contact_directly':'available';}}next[String(day)]=row;bookingHours=next;}
 function setDayRange(day:number,key:'start'|'end',value:string){bookingRanges={...bookingRanges,[String(day)]:{...(bookingRanges[String(day)]??{start:'',end:''}),[key]:value}};}
 function cycleBookingStatus(day:number,time:string){const next={...bookingHours};const row={...(next[String(day)]??{})};const current=row[time];if(!current)row[time]='available';else if(current==='available')row[time]='contact_directly';else delete row[time];next[String(day)]=row;bookingHours=next;bookingRanges={...bookingRanges,[String(day)]:rangeFrom(row)};}
 function shippingServiceChoices(shipment:any){const country=shipment.address?.country;const methods=country==='TH'?['ems_local','flash']:['ems_world'];return methods.filter(method=>settings.shipping_rates?.[`${country}:${method}`]?.length);}
 function shippingServiceLabel(service:string){return T(service==='pickup'?'Local pickup':service==='flash'?'Flash Express':service==='ems_world'?'Thailand Post EMS World':'Thailand Post EMS',service==='pickup'?'นัดรับสินค้าเอง':service==='flash'?'Flash Express':service==='ems_world'?'ไปรษณีย์ไทย EMS World':'ไปรษณีย์ไทย EMS');}
 async function get(path:string){const res=await fetch('/api/admin/'+path,{cache:'no-store'});if(!res.ok)throw Error();return await res.json();}
 async function load(){try{const [stock,shipping,review,store,hours]=await Promise.all([get('inventory'),get('shipments'),get('jobs'),get('storefront'),get('booking-hours')]);inventory=stock.inventory;shipments=shipping.shipments;shippingServices=Object.fromEntries(shipping.shipments.map((shipment:any)=>[shipment.order_id,shipment.shipping_service??shipment.fulfillment_method]));jobs=review.jobs;counts=Object.fromEntries(inventory.map(row=>[row.sku,row.on_hand]));weights=Object.fromEntries(inventory.map(row=>[row.sku,(row.weight_grams??0)/1000]));prices=Object.fromEntries(inventory.map(row=>[row.sku,{usd:(row.price_usd_minor??0)/100,jpy:row.price_jpy??0,thb:(row.price_thb_minor??0)/100}]));settings={...store.settings,shipping_rates:Object.fromEntries(Object.entries(store.settings.shipping_rates??{}).map(([key,bands]:any)=>[key,bands.map((b:any)=>({maxGrams:b.maxGrams,thb:b.thbMinor/100}))]))};bookingHours=hours.weeklyHours;bookingRanges=Object.fromEntries(weekdays.map(day=>[String(day),rangeFrom(bookingHours[String(day)]??{})]));countryOptions=store.countries.map((code:string)=>({code,name:new Intl.DisplayNames([th()?'th':'en'],{type:'region'}).of(code)??code})).sort((a:any,b:any)=>a.name.localeCompare(b.name));status='';return true;}catch{status=T('Seller tools are unavailable. Apply the required database migrations and try again.','เครื่องมือผู้ขายไม่พร้อมใช้งาน โปรดติดตั้ง migration ที่จำเป็นแล้วลองอีกครั้ง');return false;}}
 onMount(load);
 async function mutate(path:string,method:string,body:unknown){if(busy)return;busy=true;status=T('Saving…','กำลังบันทึก…');try{const res=await fetch('/api/admin/'+path,{method,headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});if(!res.ok){status=res.status===409?T('The record changed. Reload and check its current state.','ข้อมูลเปลี่ยนแปลงแล้ว โปรดโหลดใหม่และตรวจสอบสถานะ'):T('Could not save. Check the entered details.','บันทึกไม่ได้ โปรดตรวจสอบข้อมูล');return;}await load();status=T('Saved','บันทึกแล้ว');}catch{status=T('Could not save. Please try again.','บันทึกไม่ได้ โปรดลองอีกครั้ง');}finally{busy=false;}}
 function selected(code:string){return settings.allowed_countries.includes(code);}
 function toggleCountry(code:string){const countries=new Set(settings.allowed_countries);countries.has(code)?countries.delete(code):countries.add(code);settings={...settings,allowed_countries:[...countries].sort()};}
 function rateKey(code=rateCountry,service=rateService){return `${code}:${service}`;}
 function addRate(){if(!Number.isFinite(rateKg)||rateKg<=0||rateKg>30||!Number.isFinite(rateTHB)||rateTHB<0)return;const key=rateKey();const rows=[...(settings.shipping_rates[key]??[]),{maxGrams:Math.round(rateKg*1000),thb:rateTHB}].sort((a:any,b:any)=>a.maxGrams-b.maxGrams);settings={...settings,shipping_rates:{...settings.shipping_rates,[key]:rows}};}
 function removeRate(key:string,index:number){settings.shipping_rates[key]=settings.shipping_rates[key].filter((_:any,i:number)=>i!==index);settings={...settings,shipping_rates:{...settings.shipping_rates}};}
 function saveStorefront(){const enabled=settings.allowed_countries.filter((code:string)=>settings.pickup_enabled&&code==='TH'||['ems_local','ems_world','flash'].some(service=>settings.shipping_rates[`${code}:${service}`]?.length));mutate('storefront','PATCH',{allowedCountries:enabled,shippingRates:settings.shipping_rates,usdThb:settings.usd_thb?Number(settings.usd_thb):null,jpyThb:settings.jpy_thb?Number(settings.jpy_thb):null,pickupEnabled:settings.pickup_enabled});}
</script>
<div class="max-w-6xl mx-auto px-4 md:px-6 py-24 space-y-10"><h1 class="font-serif text-4xl">{T('Seller preparation','จัดการร้านค้า')}</h1><p role="status" aria-live="polite">{status}</p><button class="btn" disabled={busy} onclick={load}>{T('Reload','โหลดข้อมูลใหม่')}</button>
<section class="bg-white/5 border border-white/10 rounded-3xl p-6 space-y-5"><h2 class="font-serif text-2xl">{T('Stock, prices and gross product weight','สต๊อก ราคา และน้ำหนักรวมสินค้า')}</h2><p class="text-neutral-400">{T('Only end plugs and shakuhachi are checkout-enabled. Silicone pads are not purchasable. Set the packaged gross weight in kg; checkout uses this value for EMS. Zero means weight is not configured and checkout will stop.','ขณะนี้ซื้อผ่านระบบได้เฉพาะจุกอุดแซกโซโฟนและขลุ่ยชาคุฮาจิ แผ่นซิลิโคนยังไม่เปิดให้ซื้อ กรอกน้ำหนักรวมบรรจุภัณฑ์เป็นกิโลกรัม หากเป็นศูนย์ ระบบจะยังไม่ให้ชำระเงิน')}</p><div class="space-y-4">{#each inventory as row}<article class="rounded-2xl border border-white/10 bg-black/30 p-4 space-y-4"><h3 class="font-medium break-all">{row.sku}</h3><div class="grid grid-cols-2 md:grid-cols-6 gap-3"><label>{T('On hand','จำนวนทั้งหมด')}<input class="input w-full mt-1" type="number" min={row.reserved} step="1" bind:value={counts[row.sku]}/></label><p class="pt-1">{T('Reserved','จองแล้ว')}<br/><strong>{row.reserved}</strong></p><p class="pt-1">{T('Available','พร้อมขาย')}<br/><strong>{row.on_hand-row.reserved}</strong></p><label>{T('Gross weight (kg)','น้ำหนักรวม (กก.)')}<input class="input w-full mt-1" type="number" min="0" max="30" step="0.001" bind:value={weights[row.sku]}/></label><label>USD<input class="input w-full mt-1" type="number" min="0.01" step="0.01" bind:value={prices[row.sku].usd}/></label><label>JPY<input class="input w-full mt-1" type="number" min="1" step="1" bind:value={prices[row.sku].jpy}/></label><label>THB<input class="input w-full mt-1" type="number" min="0.01" step="0.01" bind:value={prices[row.sku].thb}/></label></div><div class="flex flex-wrap gap-3"><button class="btn btn-sm" disabled={busy||!Number.isInteger(counts[row.sku])||counts[row.sku]<row.reserved} onclick={()=>mutate('inventory','PATCH',{sku:row.sku,onHand:counts[row.sku]})}>{T('Save stock','บันทึกสต๊อก')}</button><button class="btn btn-sm" disabled={busy} onclick={()=>mutate('prices','PATCH',{sku:row.sku,...prices[row.sku]})}>{T('Save prices','บันทึกราคา')}</button><button class="btn btn-sm" disabled={busy} onclick={()=>mutate('weight','PATCH',{sku:row.sku,weightKg:weights[row.sku]})}>{T('Save weight','บันทึกน้ำหนัก')}</button></div></article>{/each}</div></section>
<section class="bg-white/5 border border-white/10 rounded-3xl p-6 space-y-5"><h2 class="font-serif text-2xl">{T('Weekly repair hours','เวลาซ่อมประจำสัปดาห์')}</h2><p class="text-neutral-300">{T('Set a weekly open-to-close range in 30-minute increments. Each appointment lasts one hour and may start every 30 minutes. Click a block to cycle Available → Contact directly → Unavailable. Confirmed bookings and busy Google Calendar times are shown to customers automatically. For one-off days or time off, add a busy event to the connected repair calendar.','ตั้งเวลาเปิดถึงปิดประจำสัปดาห์โดยเพิ่มครั้งละ 30 นาที การนัดหมายใช้เวลา 1 ชั่วโมงและเริ่มได้ทุก 30 นาที คลิกช่วงเวลาเพื่อเปลี่ยนสถานะ ว่าง → ติดต่อร้านโดยตรง → ไม่ว่าง ระบบจะแสดงรายการจองและเวลาที่มีนัดใน Google Calendar ให้อัตโนมัติ หากต้องการปิดเวลาเฉพาะวัน ให้เพิ่มกิจกรรมไม่ว่างในปฏิทินซ่อมที่เชื่อมต่อ')}</p><p class="text-sm text-neutral-400">{T('Example: Monday–Friday, 8am–6pm. Each 30-minute block sets the status for appointments starting at that time; the last online start is 5pm.','ตัวอย่าง: วันจันทร์–ศุกร์ 8:00–18:00 แต่ละช่วง 30 นาทีใช้กำหนดสถานะเวลานัดที่เริ่มในช่วงนั้น เวลาจองออนไลน์รอบสุดท้ายคือ 17:00')}</p><div class="space-y-3">{#each weekdays as day}<details class="rounded-xl border border-white/10 bg-black/20 p-4"><summary class="cursor-pointer font-medium">{weekdayName(day)}{#if bookingRanges[String(day)]?.start} · {bookingRanges[String(day)].start}–{bookingRanges[String(day)].end}{:else} · {T('Closed','ปิด')}{/if}</summary><div class="mt-4 grid sm:grid-cols-[1fr_1fr_auto] gap-3 items-end"><label>{T('Open','เปิด')}<select class="input w-full mt-1" value={bookingRanges[String(day)]?.start??''} onchange={event=>setDayRange(day,'start',event.currentTarget.value)}><option value="">—</option>{#each slotTimes as time}<option value={time}>{time}</option>{/each}</select></label><label>{T('Close','ปิด')}<select class="input w-full mt-1" value={bookingRanges[String(day)]?.end??''} onchange={event=>setDayRange(day,'end',event.currentTarget.value)}><option value="">—</option>{#each closeTimes as time}<option value={time}>{time}</option>{/each}</select></label><button class="btn btn-sm" disabled={busy||!validRange(day)} onclick={()=>applyDayRange(day)}>{T('Apply range','ใช้เวลานี้')}</button></div><div class="mt-4 overflow-x-auto"><div class="flex min-w-max gap-2">{#each slotTimes as time}{@const slotState=bookingHours[String(day)]?.[time]??'unavailable'}<button type="button" class="w-24 min-h-11 rounded-lg border px-2 py-2 text-xs focus-visible:outline focus-visible:outline-2 focus-visible:outline-amber-300" class:bg-emerald-950={slotState==='available'} class:border-emerald-500={slotState==='available'} class:bg-amber-950={slotState==='contact_directly'} class:border-amber-500={slotState==='contact_directly'} class:opacity-50={slotState==='unavailable'} aria-label={`${weekdayName(day)} ${time}: ${slotState==='available'?T('Available','ว่าง'):slotState==='contact_directly'?T('Contact directly','ติดต่อร้าน'):T('Unavailable','ไม่ว่าง')}`} onclick={()=>cycleBookingStatus(day,time)}><span class="block">{time}</span><span>{slotState==='available'?T('Available','ว่าง'):slotState==='contact_directly'?T('Contact directly','ติดต่อร้าน'):T('Unavailable','ไม่ว่าง')}</span></button>{/each}</div></div></details>{/each}</div><button class="btn btn-primary" disabled={busy} onclick={()=>mutate('booking-hours','PATCH',{weeklyHours:bookingHours})}>{T('Save weekly hours','บันทึกเวลาประจำสัปดาห์')}</button></section><section class="bg-white/5 border border-white/10 rounded-3xl p-6 space-y-5"><h2 class="font-serif text-2xl">{T('Shipping services and local pickup','บริการจัดส่งและนัดรับสินค้าเอง')}</h2><p class="text-neutral-300">{T('Configure only destinations and services confirmed as currently available. Enter each carrier rate band in THB; Checkout uses total gross weight. USD/JPY postage is converted using the values below. EMS World is weight-based; some destinations have lower limits.','เลือกเฉพาะประเทศและบริการที่ตรวจสอบแล้วว่าพร้อมให้บริการ กรอกอัตราของแต่ละบริษัทขนส่งเป็นบาทตามช่วงน้ำหนัก ระบบจะคิดจากน้ำหนักรวม ราคา USD/JPY แปลงตามอัตราด้านล่าง EMS World คิดตามน้ำหนักและบางประเทศจำกัดน้ำหนักต่ำกว่า')}</p><label class="flex gap-3 items-center"><input type="checkbox" bind:checked={settings.pickup_enabled}/>{T('Allow no-fee pickup in Thailand','เปิดให้นัดรับสินค้าเองในประเทศไทยโดยไม่มีค่าส่ง')}</label><div class="grid md:grid-cols-2 gap-4"><label>{T('THB per USD','บาทต่อดอลลาร์สหรัฐ')}<input class="input w-full mt-1" type="number" min="0.000001" step="0.000001" bind:value={settings.usd_thb}/></label><label>{T('THB per JPY','บาทต่อเยน')}<input class="input w-full mt-1" type="number" min="0.00000001" step="0.00000001" bind:value={settings.jpy_thb}/></label></div><div class="grid sm:grid-cols-4 gap-3"><label>{T('Destination','ปลายทาง')}<select class="input w-full mt-1" bind:value={rateCountry}>{#each countryOptions as c}<option value={c.code}>{c.name} ({c.code})</option>{/each}</select></label><label>{T('Service','บริการ')}<select class="input w-full mt-1" bind:value={rateService}><option value="ems_local">Thailand Post EMS (TH)</option><option value="flash">Flash Express (TH)</option><option value="ems_world">Thailand Post EMS World</option></select></label><label>{T('Rate up to (kg)','อัตรานี้ครอบคลุมถึง (กก.)')}<input class="input w-full mt-1" type="number" min="0.001" max="30" step="0.001" bind:value={rateKg}/></label><label>{T('Rate (THB)','ค่าส่ง (บาท)')}<input class="input w-full mt-1" type="number" min="0" step="0.01" bind:value={rateTHB}/></label></div><p class="text-sm text-amber-200">{T('Use each carrier’s current rates. Enable only destinations and services you have verified.','ใช้อัตราปัจจุบันของบริษัทขนส่ง และเปิดเฉพาะประเทศกับบริการที่ตรวจสอบแล้ว')}</p><button class="btn" onclick={addRate}>{T('Add rate band','เพิ่มช่วงอัตรา')}</button><div class="space-y-4">{#each Object.entries(settings.shipping_rates) as [key,bands]}{@const [code,service]=key.split(':')}<article class="border border-white/10 rounded-xl p-4"><h3>{countryOptions.find(c=>c.code===code)?.name??code} ({code}) · {service}</h3><div class="flex flex-wrap gap-2 mt-2">{#each bands as band,i}<span class="badge">≤ {(band.maxGrams/1000).toFixed(3)} kg · ฿{Number(band.thb).toFixed(2)} <button class="ml-2" aria-label={'Remove rate '+key} onclick={()=>removeRate(key,i)}>×</button></span>{/each}</div><label class="flex gap-2 items-center mt-3"><input type="checkbox" checked={selected(code)} onchange={()=>toggleCountry(code)}/>{T('Enable destination for checkout','อนุญาตให้ชำระเงินไปประเทศนี้')}</label></article>{/each}</div><button class="btn btn-primary" disabled={busy||!settings.allowed_countries.length} onclick={saveStorefront}>{T('Save shipping settings','บันทึกการจัดส่ง')}</button></section>
<section class="space-y-6"><h2 class="font-serif text-2xl">{T('Paid orders and fulfillment','คำสั่งซื้อที่ชำระแล้วและการจัดส่ง')}</h2>{#if !shipments.length}<p>{T('No paid shipments loaded.','ไม่มีรายการที่ชำระแล้ว')}</p>{/if}{#each shipments as shipment}{@const reference=historicalParcelReference(shipment.address?.country)}<article class="bg-white/5 border border-white/10 rounded-3xl p-6 space-y-4"><h3 class="break-all">{shipment.order_id}</h3><p class="break-words">{shipment.recipient?.name} · {shipment.address?.line1} · {shipment.address?.city} · {shipment.address?.postal_code} · {shipment.address?.country}</p><p>{T('Status','สถานะ')}: {shipment.status} · {T('Fulfillment','วิธีรับสินค้า')}: {shippingServiceLabel(shipment.shipping_service??shipment.fulfillment_method)}</p><p>{T('Shipping charge','ค่าส่ง')}: {shipment.shipping_minor} {shipment.currency?.toUpperCase()}</p>{#each shipment.items as item}<p>{item.quantity} × {item.name}</p>{/each}{#if shipment.hold}<div class="alert alert-warning"><strong>{T('Dispatch on hold.','ระงับการจัดส่ง')}</strong> {shipment.hold_reason}</div>{/if}{#if shipment.fulfillment_method!=='pickup'&&reference}<p class="text-neutral-400">{T('Historical 2022 reference for parcel preparation only; this does not set the checkout rate.','ข้อมูลเก่าปี 2022 ใช้เตรียมพัสดุเท่านั้น ไม่ใช่อัตราค่าส่งตอนชำระเงิน')}</p>{/if}{#if shipment.hold===false&&shipment.status==='ready'&&shipment.fulfillment_method!=='pickup'}<label class="flex gap-3"><input type="checkbox" bind:checked={confirmed[shipment.order_id]}/><span>{T('I confirmed the address, weight, postage paid and selected carrier.','ตรวจสอบที่อยู่ น้ำหนัก ค่าส่งที่ชำระ และบริษัทขนส่งที่เลือกแล้ว')}</span></label><label class="block">{T('Shipping service','บริการจัดส่ง')}<select class="input w-full mt-1" value={shippingServices[shipment.order_id]} onchange={event=>shippingServices={...shippingServices,[shipment.order_id]:event.currentTarget.value}}>{#each shippingServiceChoices(shipment) as service}<option value={service}>{shippingServiceLabel(service)}</option>{/each}</select></label><label for={'tracking-'+shipment.order_id}>{T('Tracking number','หมายเลขติดตาม')}</label><input class="input w-full" id={'tracking-'+shipment.order_id} bind:value={tracking[shipment.order_id]}/><button class="btn btn-primary" disabled={busy||!confirmed[shipment.order_id]||!shippingServiceChoices(shipment).includes(shippingServices[shipment.order_id])||!/^[A-Za-z0-9][A-Za-z0-9 -]{2,119}$/.test(tracking[shipment.order_id]??'')} onclick={()=>mutate('shipments','POST',{orderId:shipment.order_id,shippingService:shippingServices[shipment.order_id],tracking:tracking[shipment.order_id]})}>{T('Mark shipped','บันทึกว่าจัดส่งแล้ว')}</button>{:else if shipment.fulfillment_method==='pickup'&&shipment.status==='ready'}<button class="btn btn-primary" disabled={busy} onclick={()=>mutate('shipments','POST',{orderId:shipment.order_id,tracking:'PICKUP'})}>{T('Mark collected','บันทึกรับสินค้าแล้ว')}</button>{:else if shipment.status==='shipped'}<p>{T('Tracking / collection','ติดตาม / รับสินค้า')}: {shipment.tracking_number}</p>{#if shipment.tracking_url}<a class="underline text-amber-200" href={shipment.tracking_url} target="_blank" rel="noreferrer">{T('Open tracking website','เปิดเว็บไซต์ติดตามพัสดุ')}</a>{/if}{/if}{#if shipment.hold_history?.length}<div class="border-t border-white/10 pt-4"><h4>{T('Hold and release history','ประวัติการระงับและยกเลิก')}</h4>{#each shipment.hold_history as event}<p class="text-sm mt-2">{new Date(event.created_at).toLocaleString(th()?'th-TH':'en')} · {event.hold?T('Held','ระงับ'):T('Released','ยกเลิกระงับ')} · {event.actor} · {event.reason}</p>{/each}</div>{/if}</article>{/each}</section>
<section><h2 class="font-serif text-2xl mb-6">{T('Failed or review delivery jobs','งานส่งข้อมูลที่ผิดพลาดหรือต้องตรวจสอบ')}</h2><div class="overflow-x-auto"><table class="table"><thead><tr><th>ID</th><th>{T('Topic','หัวข้อ')}</th><th>{T('Status','สถานะ')}</th><th>{T('Attempts','จำนวนครั้ง')}</th></tr></thead><tbody>{#each jobs as job}<tr><td>{job.id}</td><td>{job.topic}</td><td>{job.status}</td><td>{job.attempts}</td></tr>{/each}</tbody></table></div></section></div>
